// an FCB's drive, name and extension from a command-line word (DOS's parse, INT 21h 29h): upper case, blank-padded
static void fcb_from(u8 *fcb, const char *w, size_t n)
{
  memset(fcb, 0, 16);
  memset(fcb + 1, ' ', 11);
  size_t k = 0, j = 0;
  for (; k < n && w[k] != '.' && j < 8; k++) fcb[1 + j++] = (u8)toupper((unsigned char)w[k]);
  while (k < n && w[k] != '.') k++;
  if (k < n && w[k] == '.') k++;
  for (j = 0; k < n && j < 3; k++) fcb[9 + j++] = (u8)toupper((unsigned char)w[k]);
}

